    $bP = fn($k) => (string) ($_POST[$k] ?? '');
    $bInt = function ($k, $lo, $hi, $l, $blank = false) use ($bP) {
        $v = trim($bP($k));
        if ($blank && $v === '') return;
        if (!preg_match('/^-?\d{1,10}$/', $v) || (int) $v < $lo || (int) $v > $hi) beta_ps_fail("$l must be a whole number from $lo to $hi" . ($blank ? ', or empty for unlimited.' : '.'));
    };
    $bBool = function (...$ks) use ($bP) { foreach ($ks as $k) if (isset($_POST[$k]) && $bP($k) !== '1') beta_ps_fail('Invalid on/off value.'); };
    $bText = function ($k, $lo, $hi, $l, $lines = false) use ($bP) {
        $v = trim($bP($k)); $n = mb_strlen($v);
        if ($n < $lo || $n > $hi) beta_ps_fail($lo ? "$l must be $lo to $hi characters." : "$l must be $hi characters or fewer.");
        if (preg_match($lines ? '/[\x00-\x09\x0B\x0C\x0E-\x1F\x7F]/u' : '/[\x00-\x1F\x7F]/u', $v)) beta_ps_fail("$l cannot contain control characters" . ($lines ? '.' : ' or line breaks.'));
    };
    $bItem = function () use ($bP, $db) {
        if (!preg_match('/^[1-9]\d{0,9}$/', $bP('item_id'))) beta_ps_fail('Unknown item.');
        $id = (int) $bP('item_id'); $st = $db->prepare('SELECT 1 FROM point_store_items WHERE id = ? LIMIT 1'); $st->bind_param('i', $id); $st->execute();
        $ok = (bool) $st->get_result()->fetch_row(); $st->close(); if (!$ok) beta_ps_fail('That item no longer exists.', 404);
    };
    switch ($bP('action')) {
        case 'update_settings':
            $bBool('enabled', 'paused', 'stream_online_only');
            $bInt('global_cooldown_seconds', 0, 86400, 'Global cooldown');
            $bInt('max_purchases_per_user_per_stream', 1, 1000, 'Max buys per viewer per stream', true);
            break;
        case 'save_item':
            if ($bP('item_id') !== '0') $bItem();
            $bText('title', 1, 150, 'Title'); $bText('description', 0, 500, 'Description', true);
            $bInt('cost', 1, 1000000000, 'Price');
            if (!in_array($bP('item_type'), $allowedTypes, true)) beta_ps_fail('Choose an item type.');
            if ($bP('item_type') === 'tts') $bText('tts_text', 1, 300, 'TTS text', true);
            if ($bP('item_type') === 'chat_message') { $bText('chat_text', 1, 400, 'Chat message'); if (preg_match('/^[\/.]/', trim($bP('chat_text')))) beta_ps_fail('Chat messages cannot start with / or .'); }
