            $bInt('max_per_stream', 1, 1000, 'Max per stream', true); $bInt('stock', 0, 1000000, 'Stock', true);
            $bBool('item_enabled');
            break;
        case 'delete_item': case 'toggle_item': $bItem(); break;
        default: beta_ps_fail('Unknown action.');
    }
}
